def get_scorm_runtime_spec_catalog() -> List[ScormRuntimeSpecRecord]:
    """Return complete scorm_runtime_spec registry."""
    return REGISTRY_SCORM_RUNTIME_SPEC


def query_scorm_runtime_spec_by_difficulty(difficulty_level: str) -> List[ScormRuntimeSpecRecord]:
    """Filter scorm_runtime_spec elements matching difficulty."""
    return [item for item in REGISTRY_SCORM_RUNTIME_SPEC if item.difficulty == difficulty_level]


def calculate_scorm_runtime_spec_total_weight() -> float:
    """Compute cumulative weighting of curriculum units."""
    return sum(item.weight for item in REGISTRY_SCORM_RUNTIME_SPEC)

